INSERT INTO `w_wo_sample_details` VALUES ('2119658501427838978', '2115387771433500674', '0', '05035817329389', '刘畅', '2026-11-09 13:09:03', '16466317325076496', '梁皓', '2026-11-10 12:35:18', '1', NULL, NULL, NULL, '621271385', '研发中心（上海）', NULL, '2119658294057320450', '5', NULL, NULL, NULL, NULL, 'DH-B149251', '2026-11-09 00:00:00', 'FLP2452CFL', '销售自提', '需求1：客户城市系列-武汉选中该款\n武汉_红木与汉#2	FLP2437FFL\n需要在该版本上做两个方向的优化\n方向1：忙碌时的码头\n方向2：休息空闲时的码头\n目前客户反馈核心元素不够清晰，但对该香气的喜好度很高，品牌本身为户外运动品牌，产品线主要还是基于大牌香氛上做变化\n核心：需要一笔能感受到主题\n目前该版本木质香是品牌喜好的方向需要进一步优化野性和松弛两个方向\n\n需求2：郑州需要重新选题\n客户想要表现黄河的磅礴气势与彪悍风气\n整体要有力量感，香气本身需要带有壤香感在，需要两个不同的方向感受\n该两款城市限定围绕水元素作为辅助角色，需要突出户外野生宽阔的感觉，且该城市正好对应长江黄河\n\n需求价格：500~800，600以内最佳\n需要20%香水加香产品\n需求时间：11.18', '武汉_落日码头', 'false', NULL, '20%', '5.68', '未评估', '1', '未评估', '1', '未评估', '1', '未评估', '1', '未评估', '1', NULL, '', '', NULL, NULL, '武汉_落日码头2', '1', '1136.68', NULL, NULL, NULL);
